import json, sys
data = json.load(sys.stdin)
# Find paths related to exec or process
for path, methods in data.get('paths', {}).items():
    if 'exec' in path.lower() or 'process' in path.lower() or 'command' in path.lower():
        print(f'Path: {path}')
        for method, details in methods.items():
            print(f'  {method.upper()}: {details.get(\"summary\", \"\")}')
